      "expected": "Both MCUs' VDD pins must be connected to the specified 3.3 V supply.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"216\") (name \"unconnected-(FCC2-VDD-Pad11)\") ... (node (ref \"FCC2\") (pin \"11\") (pinfunction \"VDD\"))"
