        },
        {
          "source": "netlist",
          "quote": "(net (code \"276\") (name \"unconnected-(NAVC2-VDD-Pad19)\") ... (node (ref \"NAVC2\") (pin \"19\") (pinfunction \"VDD\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"279\") (name \"unconnected-(NAVC2-VDD-Pad64)\") ... (node (ref \"NAVC2\") (pin \"64\") (pinfunction \"VDD\"))"
        },
        {
          "source": "spec",
          "quote": "3.3 V feeds both MCUs (FCC, NAVC)"
        }
      ],
      "impact": "Neither MCU can receive its core supply, so the flight-control and navigation computers will not operate.",
      "confidence": 0.99
    },
    {
      "category": "open_connection",
      "components": ["REG3"],
      "pins": ["REG3.1", "FCC2.1", "NAVC2.1"],
      "nets": ["+3.3V", "+3V3"],
      "observed": "The regulator output is on the net named +3.3V, while a separate net named +3V3 carries other circuitry; the netlist contains no connection between these distinct nets.",
      "expected": "The regulator's 3.3 V output should supply the board's 3.3 V consumers as one connected rail.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"1\") (name \"+3.3V\") ... (node (ref \"REG3\") (pin \"1\") (pinfunction \"OUT\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"2\") (name \"+3V3\") ... (node (ref \"NAVC2\") (pin \"1\") (pinfunction \"VBAT\"))"
        },
        {
          "source": "spec",
          "quote": "3.3 V feeds both MCUs (FCC, NAVC) and all I2C sensor ICs"
        }
      ],
      "impact": "The +3V3 consumers are isolated from the regulator output and will not receive power from REG3; the separately named rails also risk inconsistent behavior in the board's 3.3 V circuitry.",
      "confidence": 0.98
    },
    {
      "category": "open_connection",
      "components": ["FCC2", "R94", "C110"],
      "pins": ["FCC2.20", "FCC2.13"],
      "nets": ["unconnected-(FCC2-VREF+-Pad20)", "VREF+_FCC"],
      "observed": "The MCU's VREF+ pin 20 is unconnected, while the net named VREF+_FCC instead connects to FCC2 pin 13, whose listed function is PH1.",
      "expected": "The MCU's actual VREF+ pin should be connected to its intended reference network; the PH1 GPIO should not substitute for that pin.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"165\") (name \"VREF+_FCC\") ... (node (ref \"FCC2\") (pin \"13\") (pinfunction \"PH1\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"222\") (name \"unconnected-(FCC2-VREF+-Pad20)\") ... (node (ref \"FCC2\") (pin \"20\") (pinfunction \"VREF+\"))"
        }
      ],
      "impact": "The FCC's analog reference input is left floating, potentially making ADC measurements invalid; the intended reference filter is connected to a GPIO pin instead.",
      "confidence": 0.97
    }
  ],
  "summary": "The netlist leaves every VDD pin on both MCUs unpowered, a blocking departure from the specified 3.3 V supply design. It also separates the regulator's +3.3V net from +3V3 and leaves the FCC's actual VREF+ pin open."
}

